/* ============================================================
   Design Tokens
   ============================================================ */
:root {
  --color-bg:          #0c0c0e;
  --color-surface:     #16161a;
  --color-surface-2:   #1e1e24;
  --color-surface-3:   #26262e;
  --color-border:      #2e2e38;
  --color-accent:      #f0a500;
  --color-accent-dim:  #c98900;
  --color-accent-glow: rgba(240, 165, 0, 0.15);
  --color-sale:        #22c55e;
  --color-sale-bg:     rgba(34, 197, 94, 0.12);
  --color-text-primary:   #f0f0f2;
  --color-text-secondary: #9898a8;
  --color-text-muted:     #5a5a6e;
  --color-link-hover:  #ffd166;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 2px 12px rgba(0,0,0,.45);
  --shadow-focus: 0 0 0 3px var(--color-accent);
  --transition-fast: 150ms ease;
  --transition-std: 250ms ease;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Inter', system-ui, -apple-system, sans-serif;
  --container-max: 1280px;
  --container-pad: clamp(1rem, 4vw, 2.5rem);
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img, video { max-width: 100%; display: block; }
ul { list-style: none; }
a { color: inherit; text-decoration: none; }

/* ============================================================
   Skip Link
   ============================================================ */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 9999;
  padding: .75rem 1.5rem;
  background: var(--color-accent);
  color: #000;
  font-weight: 700;
  border-radius: 0 0 var(--radius-sm) 0;
  transform: translateY(-100%);
  transition: transform var(--transition-fast);
}
.skip-link:focus { transform: translateY(0); }

/* ============================================================
   Screen-reader-only utility
   ============================================================ */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* ============================================================
   Layout helpers
   ============================================================ */
.container {
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-pad);
}

/* ============================================================
   Focus Indicator
   ============================================================ */
:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ============================================================
   Header & Nav
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(12, 12, 14, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding-block: 1rem;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .6rem;
  flex-shrink: 0;
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--color-text-primary);
}
.site-logo:hover { color: var(--color-accent); }
.site-logo svg { flex-shrink: 0; }
.logo-mark { color: var(--color-accent); }

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav > ul {
  display: flex;
  align-items: center;
  gap: .25rem;
}
.primary-nav a,
.primary-nav button {
  display: inline-block;
  padding: .45rem .85rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  background: none;
  border: none;
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
}
.primary-nav a:hover,
.primary-nav button:hover,
.primary-nav a[aria-current="page"] {
  color: var(--color-text-primary);
  background: var(--color-surface-2);
}
.primary-nav a[aria-current="page"] {
  font-weight: 600;
  color: var(--color-accent);
}

/* Dropdown */
.nav-item { position: relative; }
.nav-dropdown {
  position: absolute;
  top: calc(100% + .5rem);
  left: 0;
  min-width: 180px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: .5rem;
  box-shadow: 0 8px 32px rgba(0,0,0,.6);
  z-index: 200;
}
.nav-dropdown[hidden] { display: none; }
.nav-dropdown a {
  display: block;
  padding: .55rem .85rem;
  font-size: .88rem;
  border-radius: var(--radius-sm);
  color: var(--color-text-secondary);
}
.nav-dropdown a:hover { color: var(--color-text-primary); background: var(--color-surface-3); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}
.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: var(--radius-sm);
  background: none;
  border: none;
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
}
.icon-btn:hover { color: var(--color-text-primary); background: var(--color-surface-2); }

.cart-badge {
  position: absolute;
  top: 2px;
  right: 2px;
  min-width: 1.1rem;
  height: 1.1rem;
  padding: 0 .25rem;
  background: var(--color-accent);
  color: #000;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 99px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ============================================================
   Search Bar
   ============================================================ */
.search-form {
  position: relative;
  flex: 0 1 320px;
}
.search-input {
  width: 100%;
  padding: .5rem 2.5rem .5rem 1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-primary);
  font-size: .88rem;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}
.search-input::placeholder { color: var(--color-text-muted); }
.search-input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent-glow);
}
.search-submit {
  position: absolute;
  right: .5rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: .2rem;
  border-radius: 4px;
}
.search-submit:hover { color: var(--color-accent); }

/* ============================================================
   Promo Banner
   ============================================================ */
.promo-banner {
  background: linear-gradient(90deg, #1a1000 0%, #211600 50%, #1a1000 100%);
  border-bottom: 1px solid rgba(240,165,0,.18);
  padding: .55rem var(--container-pad);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  font-size: .82rem;
  color: var(--color-text-secondary);
}
.promo-banner strong { color: var(--color-accent); }
.promo-banner-close {
  position: absolute;
  right: var(--container-pad);
  background: none;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  border-radius: 4px;
  padding: .2rem;
  display: flex;
  align-items: center;
}
.promo-banner-close:hover { color: var(--color-text-primary); }
.promo-banner[hidden] { display: none; }

/* ============================================================
   Hero Section
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  min-height: 520px;
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 70% 50%, rgba(240,165,0,.07) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(99,102,241,.06) 0%, transparent 70%);
  pointer-events: none;
  aria-hidden: true;
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  padding-block: 4rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .3rem .75rem;
  background: rgba(240,165,0,.1);
  border: 1px solid rgba(240,165,0,.25);
  border-radius: 99px;
  font-size: .78rem;
  font-weight: 600;
  color: var(--color-accent);
  letter-spacing: .06em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}
.eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  animation: pulse 2s infinite;
}
@media (prefers-reduced-motion: no-preference) {
  .eyebrow-dot { animation: pulse 2s infinite; }
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .5; transform: scale(.7); }
}

.hero-title {
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1rem;
}
.hero-title .accent { color: var(--color-accent); }

.hero-desc {
  font-size: 1.05rem;
  color: var(--color-text-secondary);
  max-width: 42ch;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  align-items: center;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .92rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
}
.btn:active { transform: scale(.98); }

.btn-primary {
  background: var(--color-accent);
  color: #000;
}
.btn-primary:hover { background: #ffb52a; box-shadow: 0 0 20px rgba(240,165,0,.35); }

.btn-secondary {
  background: var(--color-surface-3);
  color: var(--color-text-primary);
  border: 1px solid var(--color-border);
}
.btn-secondary:hover { background: #2e2e38; border-color: #3e3e4e; }

.btn-ghost {
  background: none;
  color: var(--color-accent);
  padding-inline: .25rem;
  border: none;
  font-size: .88rem;
}
.btn-ghost:hover { color: var(--color-link-hover); text-decoration: underline; }

.btn-sm {
  padding: .5rem 1rem;
  font-size: .82rem;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}
.stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--color-text-primary);
}
.stat-label {
  font-size: .78rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-top: .15rem;
}

/* Hero image side */
.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1rem;
}
.hero-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
}
.hero-card:first-child {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 1.25rem;
  padding: 1.25rem;
}
.hero-card-img {
  width: 90px;
  height: 90px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  flex-shrink: 0;
  background: var(--color-surface-3);
}
.hero-mini-card {
  padding: 1.25rem;
}
.hero-card-badge {
  display: inline-block;
  padding: .2rem .6rem;
  background: var(--color-sale-bg);
  color: var(--color-sale);
  font-size: .72rem;
  font-weight: 700;
  border-radius: 4px;
  letter-spacing: .04em;
  margin-bottom: .5rem;
}
.hero-card-name {
  font-size: .92rem;
  font-weight: 600;
  margin-bottom: .25rem;
}
.hero-card-price {
  font-size: .82rem;
  color: var(--color-text-muted);
}
.hero-card-price strong { color: var(--color-text-primary); }
.hero-card-price del { color: var(--color-text-muted); font-size: .78rem; }

/* ============================================================
   Section Common
   ============================================================ */
.section {
  padding-block: 4rem;
}
.section + .section {
  border-top: 1px solid var(--color-border);
}
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-title {
  font-size: clamp(1.3rem, 3vw, 1.8rem);
  font-weight: 800;
  letter-spacing: -.02em;
}
.section-subtitle {
  font-size: .9rem;
  color: var(--color-text-muted);
  margin-top: .3rem;
}

/* ============================================================
   Category Pills
   ============================================================ */
.category-strip {
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}
.category-list {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 2px;
}
.category-list::-webkit-scrollbar { display: none; }
.category-pill {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .55rem 1.1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 99px;
  font-size: .82rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast), border-color var(--transition-fast);
  text-decoration: none;
}
.category-pill:hover,
.category-pill[aria-current="true"] {
  color: var(--color-accent);
  background: rgba(240,165,0,.08);
  border-color: rgba(240,165,0,.3);
}
.category-pill[aria-current="true"] { font-weight: 600; }
.category-icon { font-size: 1rem; }

/* ============================================================
   Product Cards
   ============================================================ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-std), box-shadow var(--transition-std), transform var(--transition-std);
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover {
    border-color: rgba(240,165,0,.3);
    box-shadow: 0 8px 32px rgba(0,0,0,.5);
    transform: translateY(-2px);
  }
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 4/3;
  background: var(--color-surface-2);
  overflow: hidden;
}
.product-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-std);
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover .product-img { transform: scale(1.04); }
}

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .2rem .55rem;
  border-radius: 4px;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-sale    { background: var(--color-sale-bg);   color: var(--color-sale); }
.badge-new     { background: rgba(99,102,241,.15);   color: #a5b4fc; }
.badge-hot     { background: rgba(239,68,68,.12);    color: #fca5a5; }
.badge-limited { background: rgba(245,158,11,.1);    color: #fcd34d; }

.product-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
  width: 2rem;
  height: 2rem;
  background: rgba(12,12,14,.7);
  border: 1px solid var(--color-border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
  backdrop-filter: blur(4px);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] {
  color: #f87171;
  background: rgba(239,68,68,.1);
}
.product-wishlist[aria-pressed="true"] { border-color: rgba(239,68,68,.3); }

.product-body {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
  flex: 1;
}

.product-category {
  font-size: .7rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: .07em;
}

.product-name {
  font-size: .92rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--color-text-primary);
  text-decoration: none;
  display: block;
}
.product-name:hover { color: var(--color-accent); }

.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .78rem;
}
.stars { color: var(--color-accent); letter-spacing: -.05em; font-size: .85rem; }
.review-count { color: var(--color-text-muted); }

.product-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: auto;
  padding-top: .35rem;
}
.price-current { font-size: 1rem; font-weight: 700; }
.price-original { font-size: .82rem; color: var(--color-text-muted); text-decoration: line-through; }
.price-discount {
  font-size: .72rem;
  font-weight: 700;
  color: var(--color-sale);
  background: var(--color-sale-bg);
  padding: .1rem .4rem;
  border-radius: 4px;
}

.product-footer {
  padding: .75rem 1rem 1rem;
  border-top: 1px solid var(--color-border);
}
.btn-add-cart {
  width: 100%;
  justify-content: center;
  padding-block: .6rem;
}

/* ============================================================
   Deals Section
   ============================================================ */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 1.25rem;
}

.deal-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
}

.deal-card--hero {
  grid-column: 1 / 7;
  grid-row: 1 / 3;
  background: linear-gradient(145deg, #1a1200, #1e1600, var(--color-surface));
}

.deal-card--wide {
  grid-column: 7 / 13;
}

.deal-card-img {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}
.deal-card--hero .deal-card-img { aspect-ratio: 4/3; }

.deal-card-body {
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: .6rem;
  flex: 1;
}

.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .25rem .65rem;
  border-radius: 99px;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.tag-flash { background: rgba(239,68,68,.12); color: #fca5a5; border: 1px solid rgba(239,68,68,.2); }
.tag-bundle { background: rgba(99,102,241,.12); color: #a5b4fc; border: 1px solid rgba(99,102,241,.2); }
.tag-clearance { background: rgba(245,158,11,.1); color: #fcd34d; border: 1px solid rgba(245,158,11,.2); }

.deal-title {
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -.01em;
  line-height: 1.3;
}
.deal-card--hero .deal-title { font-size: 1.5rem; }

.deal-desc { font-size: .85rem; color: var(--color-text-secondary); line-height: 1.6; }

.deal-price-block {
  display: flex;
  align-items: baseline;
  gap: .6rem;
  flex-wrap: wrap;
}
.deal-price-new { font-size: 1.4rem; font-weight: 800; }
.deal-card--hero .deal-price-new { font-size: 1.8rem; }
.deal-price-old { font-size: .9rem; color: var(--color-text-muted); text-decoration: line-through; }
.deal-save {
  padding: .2rem .55rem;
  background: var(--color-sale-bg);
  color: var(--color-sale);
  font-size: .75rem;
  font-weight: 700;
  border-radius: 4px;
}

/* Countdown timer */
.deal-countdown {
  display: flex;
  gap: .5rem;
  align-items: center;
  font-size: .78rem;
  color: var(--color-text-muted);
}
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--color-surface-3);
  border-radius: var(--radius-sm);
  padding: .3rem .5rem;
  min-width: 36px;
}
.countdown-num {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text-primary);
  font-variant-numeric: tabular-nums;
}
.countdown-label { font-size: .6rem; text-transform: uppercase; letter-spacing: .05em; color: var(--color-text-muted); }
.countdown-sep { font-weight: 700; color: var(--color-accent); align-self: flex-start; margin-top: .35rem; }

/* ============================================================
   Editorial / Content Cards
   ============================================================ */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-std);
}
@media (prefers-reduced-motion: no-preference) {
  .editorial-card:hover { border-color: rgba(240,165,0,.25); }
}

.editorial-img {
  aspect-ratio: 16/9;
  width: 100%;
  object-fit: cover;
  background: var(--color-surface-3);
}

.editorial-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: .7rem;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .75rem;
  color: var(--color-text-muted);
}
.editorial-category {
  padding: .2rem .6rem;
  border-radius: 4px;
  background: rgba(240,165,0,.08);
  color: var(--color-accent);
  font-weight: 600;
  font-size: .72rem;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.editorial-title {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -.01em;
}
.editorial-title a {
  color: var(--color-text-primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}
.editorial-title a:hover { color: var(--color-accent); }

.editorial-excerpt {
  font-size: .86rem;
  color: var(--color-text-secondary);
  line-height: 1.65;
  flex: 1;
}

.editorial-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: .75rem;
  border-top: 1px solid var(--color-border);
  font-size: .78rem;
  color: var(--color-text-muted);
  gap: .5rem;
  flex-wrap: wrap;
}
.editorial-author {
  display: flex;
  align-items: center;
  gap: .5rem;
}
.author-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-surface-3);
  overflow: hidden;
  flex-shrink: 0;
}
.author-avatar img { width: 100%; height: 100%; object-fit: cover; }
.read-more {
  color: var(--color-accent);
  font-weight: 600;
  font-size: .78rem;
  text-decoration: none;
}
.read-more:hover { color: var(--color-link-hover); text-decoration: underline; }

/* ============================================================
   Newsletter Section
   ============================================================ */
.newsletter-section {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  padding-block: 4rem;
  text-align: center;
}
.newsletter-inner {
  max-width: 520px;
  margin-inline: auto;
}
.newsletter-icon {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}
.newsletter-title {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: .5rem;
}
.newsletter-desc {
  color: var(--color-text-secondary);
  font-size: .9rem;
  margin-bottom: 1.75rem;
}
.newsletter-form {
  display: flex;
  gap: .5rem;
}
.newsletter-input {
  flex: 1;
  padding: .75rem 1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-primary);
  font-size: .9rem;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}
.newsletter-input::placeholder { color: var(--color-text-muted); }
.newsletter-input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent-glow);
}
.newsletter-note {
  margin-top: .85rem;
  font-size: .75rem;
  color: var(--color-text-muted);
}

/* Status message */
.newsletter-status {
  margin-top: .75rem;
  font-size: .88rem;
  font-weight: 500;
  min-height: 1.4em;
}
.newsletter-status:empty { display: none; }
.status-success { color: var(--color-sale); }
.status-error { color: #f87171; }

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-top: 3.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
}

.footer-brand p {
  font-size: .85rem;
  color: var(--color-text-muted);
  margin-top: .75rem;
  max-width: 30ch;
  line-height: 1.65;
}
.footer-social {
  display: flex;
  gap: .5rem;
  margin-top: 1.25rem;
}
.social-link {
  width: 2.2rem;
  height: 2.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  text-decoration: none;
  transition: color var(--transition-fast), background var(--transition-fast), border-color var(--transition-fast);
}
.social-link:hover {
  color: var(--color-accent);
  background: rgba(240,165,0,.08);
  border-color: rgba(240,165,0,.25);
}

.footer-col-title {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: .55rem; }
.footer-links a {
  font-size: .86rem;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--transition-fast);
}
.footer-links a:hover { color: var(--color-text-primary); }

.footer-bottom {
  border-top: 1px solid var(--color-border);
  padding-block: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: .78rem;
  color: var(--color-text-muted);
}
.footer-legal { display: flex; gap: 1.25rem; flex-wrap: wrap; }
.footer-legal a { color: var(--color-text-muted); text-decoration: none; }
.footer-legal a:hover { color: var(--color-text-secondary); text-decoration: underline; }

/* Payment icons strip */
.payment-icons {
  display: flex;
  gap: .4rem;
  align-items: center;
  flex-wrap: wrap;
}
.payment-icon {
  padding: .2rem .5rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-size: .65rem;
  font-weight: 700;
  color: var(--color-text-muted);
  letter-spacing: .04em;
  text-transform: uppercase;
}

/* ============================================================
   Mobile nav drawer
   ============================================================ */
.nav-drawer {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: flex;
  pointer-events: none;
}
.nav-drawer[aria-hidden="false"] { pointer-events: auto; }

.nav-drawer-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.7);
  opacity: 0;
  transition: opacity var(--transition-std);
}
.nav-drawer[aria-hidden="false"] .nav-drawer-backdrop { opacity: 1; }

.nav-drawer-panel {
  position: relative;
  width: min(320px, 85vw);
  background: var(--color-surface);
  border-right: 1px solid var(--color-border);
  height: 100%;
  overflow-y: auto;
  padding: 1.5rem;
  transform: translateX(-100%);
  transition: transform var(--transition-std);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.nav-drawer[aria-hidden="false"] .nav-drawer-panel { transform: translateX(0); }

.drawer-close-btn {
  display: flex;
  align-self: flex-end;
  background: none;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  border-radius: var(--radius-sm);
  padding: .25rem;
}
.drawer-close-btn:hover { color: var(--color-text-primary); }

.drawer-nav-links { display: flex; flex-direction: column; gap: .25rem; }
.drawer-nav-links a {
  display: block;
  padding: .7rem 1rem;
  border-radius: var(--radius-sm);
  font-size: .95rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: background var(--transition-fast), color var(--transition-fast);
}
.drawer-nav-links a:hover { background: var(--color-surface-2); color: var(--color-text-primary); }

/* ============================================================
   Responsive Breakpoints
   ============================================================ */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--hero { grid-column: 1 / -1; grid-row: auto; }
  .deal-card--wide { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 768px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .primary-nav { display: none; }
  .search-form { display: none; }
  .menu-toggle { display: flex; }
  .hero-stats { gap: 1.25rem; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--hero,
  .deal-card--wide { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr; gap: 1.75rem; }
  .newsletter-form { flex-direction: column; }
}

@media (max-width: 480px) {
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   Forced Colors (High Contrast mode)
   ============================================================ */
@media (forced-colors: active) {
  .btn-primary { forced-color-adjust: none; background: ButtonText; color: ButtonFace; }
  .product-card,
  .deal-card,
  .editorial-card { border: 1px solid ButtonText; }
  .cart-badge { background: Highlight; color: HighlightText; }
  .skip-link { background: Highlight; color: HighlightText; }
  .eyebrow-dot { background: Highlight; }
}

