const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

// ── Promo Banner ──────────────────────────────────────────────
function initPromoBanner() {
  const banner = $('#promo-banner');
  const closeBtn = $('#promo-banner-close');
  if (!banner || !closeBtn) return;

  closeBtn.addEventListener('click', () => {
    banner.hidden = true;
  });
}

// ── Primary Nav Dropdowns ─────────────────────────────────────
function initNavDropdowns() {
  $$('.nav-toggle').forEach(trigger => {
    const panelId = trigger.getAttribute('aria-controls');
    const panel = document.getElementById(panelId);
    if (!panel) return;

    function open() {
      trigger.setAttribute('aria-expanded', 'true');
      panel.removeAttribute('hidden');
    }
    function close() {
      trigger.setAttribute('aria-expanded', 'false');
      panel.setAttribute('hidden', '');
    }

    trigger.addEventListener('click', () => {
      const isOpen = trigger.getAttribute('aria-expanded') === 'true';
      // Close all others first
      $$('.nav-toggle').forEach(t => {
        if (t !== trigger) {
          t.setAttribute('aria-expanded', 'false');
          const p = document.getElementById(t.getAttribute('aria-controls'));
          if (p) p.setAttribute('hidden', '');
        }
      });
      isOpen ? close() : open();
    });

    // Close on Escape
    trigger.addEventListener('keydown', e => {
      if (e.key === 'Escape') { close(); trigger.focus(); }
    });
    panel.addEventListener('keydown', e => {
      if (e.key === 'Escape') { close(); trigger.focus(); }
    });

    // Close when focus leaves the nav item entirely
    const navItem = trigger.closest('.nav-item');
    navItem?.addEventListener('focusout', e => {
      if (!navItem.contains(e.relatedTarget)) close();
    });
  });

  // Click outside closes all
  document.addEventListener('click', e => {
    if (!e.target.closest('.nav-item')) {
      $$('.nav-toggle').forEach(t => {
        t.setAttribute('aria-expanded', 'false');
        const p = document.getElementById(t.getAttribute('aria-controls'));
        if (p) p.setAttribute('hidden', '');
      });
    }
  });
}

// ── Mobile Nav Drawer ─────────────────────────────────────────
function initMobileDrawer() {
  const openBtn = $('#menu-toggle');
  const drawer = $('#nav-drawer');
  const closeBtn = $('#drawer-close');
  const backdrop = $('#drawer-backdrop');
  if (!openBtn || !drawer) return;

  function openDrawer() {
    drawer.setAttribute('aria-hidden', 'false');
    drawer.removeAttribute('inert');
    document.body.style.overflow = 'hidden';
    closeBtn?.focus();
  }
  function closeDrawer() {
    drawer.setAttribute('aria-hidden', 'true');
    drawer.setAttribute('inert', '');
    document.body.style.overflow = '';
    openBtn.focus();
  }

  openBtn.addEventListener('click', openDrawer);
  closeBtn?.addEventListener('click', closeDrawer);
  backdrop?.addEventListener('click', closeDrawer);

  drawer.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeDrawer();
  });
}

// ── Wishlist Toggles ──────────────────────────────────────────
function initWishlistButtons() {
  $$('.product-wishlist').forEach(btn => {
    btn.addEventListener('click', () => {
      const pressed = btn.getAttribute('aria-pressed') === 'true';
      btn.setAttribute('aria-pressed', String(!pressed));
      // Update label to reflect state
      const productName = btn.dataset.product || 'item';
      btn.setAttribute(
        'aria-label',
        pressed ? `Save ${productName} to wishlist` : `Remove ${productName} from wishlist`
      );
    });
  });
}

// ── Add to Cart ───────────────────────────────────────────────
function initAddToCart() {
  const cartCountEl = $('#cart-count');
  let cartCount = 0;

  $$('.btn-add-cart').forEach(btn => {
    btn.addEventListener('click', () => {
      cartCount++;
      if (cartCountEl) {
        cartCountEl.textContent = cartCount;
        cartCountEl.removeAttribute('hidden');
      }

      // Visual feedback
      const original = btn.textContent;
      btn.textContent = 'Added ✓';
      btn.disabled = true;
      setTimeout(() => {
        btn.textContent = original;
        btn.disabled = false;
      }, 1400);

      // Live region announcement
      announceToScreenReader(`${btn.dataset.product || 'Item'} added to cart`);
    });
  });
}

// ── Live Region Helper ────────────────────────────────────────
let liveRegion;
function announceToScreenReader(message) {
  if (!liveRegion) {
    liveRegion = document.createElement('div');
    liveRegion.setAttribute('aria-live', 'polite');
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.className = 'sr-only';
    document.body.appendChild(liveRegion);
  }
  liveRegion.textContent = '';
  // Brief delay so screen readers detect the change
  requestAnimationFrame(() => { liveRegion.textContent = message; });
}

// ── Countdown Timer ───────────────────────────────────────────
function initCountdown() {
  const displays = $$('[data-countdown]');
  if (!displays.length) return;

  // Respect reduced-motion: update less frequently
  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const interval = prefersReduced ? 60000 : 1000;

  // Target: 8h 42m 17s from now (demo)
  let remaining = 8 * 3600 + 42 * 60 + 17;

  function update() {
    if (remaining <= 0) return;
    remaining--;
    const h = Math.floor(remaining / 3600);
    const m = Math.floor((remaining % 3600) / 60);
    const s = remaining % 60;

    displays.forEach(el => {
      const hEl = el.querySelector('[data-unit="h"]');
      const mEl = el.querySelector('[data-unit="m"]');
      const sEl = el.querySelector('[data-unit="s"]');
      if (hEl) hEl.textContent = String(h).padStart(2, '0');
      if (mEl) mEl.textContent = String(m).padStart(2, '0');
      if (sEl) sEl.textContent = String(s).padStart(2, '0');
    });

    // Update accessible time label periodically
    if (remaining % 60 === 0) {
      displays.forEach(el => {
        el.setAttribute('aria-label', `Flash sale ends in ${h} hours ${m} minutes`);
      });
    }
  }
  update();
  setInterval(update, interval);
}

// ── Category Pill Active State ────────────────────────────────
function initCategoryPills() {
  const pills = $$('.category-pill');
  pills.forEach(pill => {
    pill.addEventListener('click', e => {
      e.preventDefault();
      pills.forEach(p => p.removeAttribute('aria-current'));
      pill.setAttribute('aria-current', 'true');
    });
  });
}

// ── Newsletter Form ───────────────────────────────────────────
function initNewsletterForm() {
  const form = $('#newsletter-form');
  const status = $('#newsletter-status');
  if (!form || !status) return;

  form.addEventListener('submit', e => {
    e.preventDefault();
    const emailInput = form.querySelector('input[type="email"]');
    const email = emailInput?.value.trim();

    if (!email) {
      status.textContent = 'Please enter a valid email address.';
      status.className = 'newsletter-status status-error';
      emailInput?.focus();
      return;
    }

    // Simulate async subscribe
    const submitBtn = form.querySelector('button[type="submit"]');
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Subscribing…'; }

    setTimeout(() => {
      status.textContent = '🎉 You're subscribed! Welcome to the club.';
      status.className = 'newsletter-status status-success';
      form.reset();
      if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'Subscribe'; }
    }, 900);
  });
}

// ── Init ──────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  initPromoBanner();
  initNavDropdowns();
  initMobileDrawer();
  initWishlistButtons();
  initAddToCart();
  initCountdown();
  initCategoryPills();
  initNewsletterForm();
});
