  const status = $('#newsletter-status');
  if (!form || !status) return;

  form.addEventListener('submit', e => {
    e.preventDefault();
    const emailInput = form.querySelector('input[type="email"]');
    const email = emailInput?.value.trim();

    if (!email) {
      status.textContent = 'Please enter a valid email address.';
      status.className = 'newsletter-status status-error';
      emailInput?.focus();
      return;
    }

    // Simulate async subscribe
    const submitBtn = form.querySelector('button[type="submit"]');
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Subscribing…'; }

    setTimeout(() => {
      status.textContent = '🎉 You're subscribed! Welcome to the club.';
      status.className = 'newsletter-status status-success';
      form.reset();
      if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'Subscribe'; }
    }, 900);
  });
}

