}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img, video { max-width: 100%; display: block; }
ul { list-style: none; }
a { color: inherit; text-decoration: none; }

/* ============================================================
   Skip Link
   ============================================================ */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 9999;
  padding: .75rem 1.5rem;
  background: var(--color-accent);
  color: #000;
  font-weight: 700;
  border-radius: 0 0 var(--radius-sm) 0;
  transform: translateY(-100%);
  transition: transform var(--transition-fast);
}
.skip-link:focus { transform: translateY(0); }

/* ============================================================
   Screen-reader-only utility
   ============================================================ */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* ============================================================
   Layout helpers
   ============================================================ */
.container {
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-pad);
}

/* ============================================================
   Focus Indicator
   ============================================================ */
:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ============================================================
   Header & Nav
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(12, 12, 14, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding-block: 1rem;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .6rem;
  flex-shrink: 0;
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--color-text-primary);
}
.site-logo:hover { color: var(--color-accent); }
.site-logo svg { flex-shrink: 0; }
.logo-mark { color: var(--color-accent); }

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav > ul {
  display: flex;
  align-items: center;
  gap: .25rem;
}
.primary-nav a,
.primary-nav button {
  display: inline-block;
  padding: .45rem .85rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  background: none;
  border: none;
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
}
.primary-nav a:hover,
.primary-nav button:hover,
.primary-nav a[aria-current="page"] {
  color: var(--color-text-primary);
  background: var(--color-surface-2);
}
.primary-nav a[aria-current="page"] {
  font-weight: 600;
  color: var(--color-accent);
}

/* Dropdown */
.nav-item { position: relative; }
.nav-dropdown {
  position: absolute;
  top: calc(100% + .5rem);
  left: 0;
  min-width: 180px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: .5rem;
  box-shadow: 0 8px 32px rgba(0,0,0,.6);
  z-index: 200;
}
.nav-dropdown[hidden] { display: none; }
.nav-dropdown a {
  display: block;
  padding: .55rem .85rem;
  font-size: .88rem;
  border-radius: var(--radius-sm);
  color: var(--color-text-secondary);
}
.nav-dropdown a:hover { color: var(--color-text-primary); background: var(--color-surface-3); }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}
.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: var(--radius-sm);
  background: none;
  border: none;
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
}
.icon-btn:hover { color: var(--color-text-primary); background: var(--color-surface-2); }

.cart-badge {
  position: absolute;
  top: 2px;
  right: 2px;
  min-width: 1.1rem;
  height: 1.1rem;
  padding: 0 .25rem;
  background: var(--color-accent);
  color: #000;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 99px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ============================================================
   Search Bar
   ============================================================ */
.search-form {
  position: relative;
  flex: 0 1 320px;
}
.search-input {
  width: 100%;
  padding: .5rem 2.5rem .5rem 1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-primary);
  font-size: .88rem;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}
.search-input::placeholder { color: var(--color-text-muted); }
.search-input:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-accent-glow);
}
.search-submit {
  position: absolute;
  right: .5rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: .2rem;
  border-radius: 4px;
}
.search-submit:hover { color: var(--color-accent); }

/* ============================================================
   Promo Banner
   ============================================================ */
.promo-banner {
  background: linear-gradient(90deg, #1a1000 0%, #211600 50%, #1a1000 100%);
  border-bottom: 1px solid rgba(240,165,0,.18);
  padding: .55rem var(--container-pad);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  font-size: .82rem;
  color: var(--color-text-secondary);
}
.promo-banner strong { color: var(--color-accent); }
.promo-banner-close {
  position: absolute;
  right: var(--container-pad);
  background: none;
  border: none;
  color: var(--color-text-muted);
  cursor: pointer;
  border-radius: 4px;
  padding: .2rem;
  display: flex;
  align-items: center;
}
.promo-banner-close:hover { color: var(--color-text-primary); }
.promo-banner[hidden] { display: none; }

/* ============================================================
   Hero Section
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  min-height: 520px;
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 70% 50%, rgba(240,165,0,.07) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(99,102,241,.06) 0%, transparent 70%);
  pointer-events: none;
  aria-hidden: true;
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  padding-block: 4rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .3rem .75rem;
  background: rgba(240,165,0,.1);
  border: 1px solid rgba(240,165,0,.25);
  border-radius: 99px;
  font-size: .78rem;
  font-weight: 600;
  color: var(--color-accent);
  letter-spacing: .06em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}
.eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  animation: pulse 2s infinite;
}
@media (prefers-reduced-motion: no-preference) {
  .eyebrow-dot { animation: pulse 2s infinite; }
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .5; transform: scale(.7); }
}

.hero-title {
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1rem;
}
.hero-title .accent { color: var(--color-accent); }

.hero-desc {
  font-size: 1.05rem;
  color: var(--color-text-secondary);
  max-width: 42ch;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  align-items: center;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .92rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
}
.btn:active { transform: scale(.98); }

.btn-primary {
  background: var(--color-accent);
  color: #000;
}
.btn-primary:hover { background: #ffb52a; box-shadow: 0 0 20px rgba(240,165,0,.35); }

.btn-secondary {
  background: var(--color-surface-3);
  color: var(--color-text-primary);
  border: 1px solid var(--color-border);
}
.btn-secondary:hover { background: #2e2e38; border-color: #3e3e4e; }

.btn-ghost {
  background: none;
